const data = $input.first().json;
const body = data.body || data;

const stats = body.stats || {};
const suite = body.suite || 'Playwright Regression - BUPA';
const fecha = body.fecha || new Date().toLocaleString('es-CL', { timeZone: 'America/Santiago' });
const fechaISO = new Date().toISOString().split('T')[0];
const testResults = body.results || [];

const totalTests = stats.tests || 0;
const passes = stats.passes || 0;
const failures = stats.failures || 0;
const skipped = totalTests - passes - failures;
const durationMs = stats.duration || 0;
const durationSec = Math.round(durationMs / 1000);
const durationStr = durationSec >= 60
  ? Math.floor(durationSec / 60) + 'm ' + (durationSec % 60) + 's'
  : durationSec + 's';

const passRate = totalTests > 0 ? Math.round((passes / totalTests) * 100) : 0;
const allPassed = failures === 0;
const statusText = allPassed ? 'PASS' : 'FAIL';

// Spec label dinamico
const specFiles = body.specFiles || [...new Set(testResults.map(r => r.spec))];
const folders = body.folders || [...new Set(testResults.map(r => r.folder).filter(Boolean))];
let specLabel;
if (specFiles.length === 1) {
  specLabel = specFiles[0];
} else if (specFiles.length > 1) {
  specLabel = folders.join(', ') + ' (' + specFiles.length + ' specs)';
} else {
  specLabel = suite;
}

// Specs que fallaron
const failedSpecs = testResults
  .filter(t => t.state === 'failed')
  .map(t => t.spec + ' → ' + t.title)
  .join(', ') || 'Ninguno';

// Subject
const subject = 'Portal Pacientes \u{1F9EA} Playwright# ' + specLabel + ' ' + statusText + ' \u2014 ' + passes + '\u2705 ' + failures + '\u274C | ' + fecha;

// Badge
const badgeHtml = allPassed
  ? '<span style="background:#F0FDF4; color:#16A34A; padding:6px 16px; border-radius:16px; font-weight:700; font-size:13px; white-space:nowrap;">\u2705 TODO PASSED</span>'
  : '<span style="background:#FEF2F2; color:#DC2626; padding:6px 16px; border-radius:16px; font-weight:700; font-size:13px; white-space:nowrap;">\u274C HAY FALLOS</span>';

// Pass rate badge
const prColor = passRate >= 95 ? '#16A34A' : passRate >= 80 ? '#F59E0B' : '#DC2626';
const prBg = passRate >= 95 ? '#F0FDF4' : passRate >= 80 ? '#FFFBEB' : '#FEF2F2';
const passRateBadge = '<span style="background:' + prBg + '; color:' + prColor + '; padding:3px 10px; border-radius:12px; font-weight:700; font-size:11px;">Pass Rate: ' + passRate + '%</span>';

// Cards
const cardHtml = (value, label, color, bg) => {
  return '<td width="20%" style="padding:4px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:' + bg + '; border-left:4px solid ' + color + '; border-radius:6px;"><tr><td style="padding:14px 16px;"><div style="font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:28px; font-weight:700; color:' + color + '; line-height:1;">' + value + '</div><div style="font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:10px; font-weight:700; letter-spacing:1px; color:#64748B; text-transform:uppercase; margin-top:4px;">' + label + '</div></td></tr></table></td>';
};

const cards = cardHtml(passes, '\u2705 PASADOS', '#16A34A', '#F0FDF4')
  + cardHtml(failures, '\u274C FALLIDOS', '#DC2626', '#FEF2F2')
  + cardHtml(skipped, '\u26A0\uFE0F SKIPPED', '#F59E0B', '#FFFBEB')
  + cardHtml(passRate + '%', '\u{1F4CA} PASS RATE', prColor, prBg)
  + cardHtml(durationStr, '\u23F1 DURACION', '#2563EB', '#EFF6FF');

// Table rows
const tableRows = testResults.map((t) => {
  let sColor, sBg, sLabel;
  if (t.state === 'passed') { sColor = '#16A34A'; sBg = '#F0FDF4'; sLabel = 'PASSED'; }
  else if (t.state === 'failed') { sColor = '#DC2626'; sBg = '#FEF2F2'; sLabel = 'FAILED'; }
  else { sColor = '#F59E0B'; sBg = '#FFFBEB'; sLabel = 'SKIPPED'; }
  const dot = t.state === 'passed' ? '\u{1F7E2}' : t.state === 'failed' ? '\u{1F534}' : '\u{1F7E1}';
  const errorText = t.err ? (t.err.length > 200 ? t.err.substring(0, 200) + '...' : t.err) : '\u2014';

  return '<tr>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:16px; text-align:center;">' + dot + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; font-weight:600; color:#0747A6; white-space:nowrap;">' + (t.spec || 'N/A') + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#1E293B;">' + (t.title || '') + '</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; text-align:center;"><span style="background:' + sBg + '; color:' + sColor + '; padding:3px 10px; border-radius:12px; font-weight:700; font-size:11px; letter-spacing:0.5px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif;">' + sLabel + '</span></td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:13px; color:#2563EB; font-weight:600; text-align:center;">' + t.duration + 'ms</td>'
    + '<td style="padding:10px 12px; border-bottom:1px solid #E2E8F0; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; color:#94A3B8; max-width:220px; word-break:break-word;">' + errorText + '</td>'
    + '</tr>';
}).join('');

// Full HTML
const htmlBody = '<div style="font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; max-width:820px; margin:0 auto; background:#F4F6FB;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#0D1846;">'
  + '<tr><td style="padding:28px 28px;" valign="top">'
  + '<div style="color:#CFE2FF; font-size:11px; letter-spacing:3px; text-transform:uppercase; font-weight:700;">BUPA CHILE \u00B7 PORTAL PACIENTES</div>'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="margin-top:10px;"><tr>'
  + '<td style="vertical-align:middle;">'
  + '<div style="color:#FFFFFF; font-size:18px; font-weight:700;">'
  + '<span style="background:rgba(255,255,255,0.15); padding:3px 10px; border-radius:5px; margin-right:6px; font-size:13px; font-weight:800;">Playwright</span>'
  + 'QA Automation Report \u2014 ' + specLabel + '</div>'
  + '<div style="color:#CFE2FF; font-size:13px; margin-top:6px;">' + totalTests + ' test(s) ejecutados \u00B7 ' + fecha + ' \u00B7 ' + passRateBadge + '</div>'
  + '</td>'
  + '<td style="text-align:right; vertical-align:middle;">' + badgeHtml + '</td>'
  + '</tr></table>'
  + '</td></tr></table>'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:16px 20px;">'
  + '<tr>' + cards + '</tr></table>'
  + '<div style="padding:4px 20px 8px;"><div style="font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:12px; font-weight:700; color:#64748B; letter-spacing:1.5px; text-transform:uppercase; border-bottom:2px solid #E2E8F0; padding-bottom:8px;">DETALLE DE TESTS</div></div>'
  + '<div style="padding:0 20px 24px; overflow-x:auto;">'
  + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse; background:#FFFFFF; border-radius:6px; overflow:hidden; box-shadow:0 1px 3px rgba(15,23,42,0.08);">'
  + '<thead><tr style="background:#F4F6F8;">'
  + '<th style="padding:10px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#64748B; width:30px;"></th>'
  + '<th align="left" style="padding:10px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Spec</th>'
  + '<th align="left" style="padding:10px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Test Case</th>'
  + '<th align="center" style="padding:10px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Estado</th>'
  + '<th align="center" style="padding:10px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Duracion</th>'
  + '<th align="left" style="padding:10px 12px; font-family:Montserrat,Segoe UI,Helvetica,Arial,sans-serif; font-size:11px; letter-spacing:1px; text-transform:uppercase; color:#64748B;">Error</th>'
  + '</tr></thead>'
  + '<tbody>' + tableRows + '</tbody></table></div>'
  + '<div style="padding:14px 20px; font-size:11px; color:#94A3B8; text-align:center; border-top:1px solid #E2E8F0;">'
  + 'Generado autom\u00E1ticamente \u2014 WF3 QA Automation Report \u00B7 Portal Pacientes'
  + '</div></div>';

// Google Sheet row data
const sheetRow = {
  fecha: fechaISO,
  hora: fecha,
  spec: specLabel,
  total: totalTests,
  passed: passes,
  failed: failures,
  skipped: skipped,
  passRate: passRate,
  duracion: durationStr,
  estado: statusText,
  failedSpecs: failedSpecs
};

return [{ json: { subject, body: htmlBody, sheetRow } }];

