  + '<div style="color:#CFE2FF; font-size:13px; margin-top:6px;">' + totalTests + ' test(s) ejecutados \u00B7 ' + fecha + '</div>'
  + '</td>'
  + '<td style="text-align:right; vertical-align:middle;">' + badgeHtml + '</td>'
